interface CacheEntry { key: string }
interface AuthHint { key: string }

const hint: AuthHint = { key: "sess-1" };
const entry: CacheEntry = hint; // TS: OK — same shape

// At runtime this is just: const entry = hint;
// No CacheEntry or AuthHint type exists in the .js file

class CacheEntry
{
    public string Key { get; init; } = "";
}

class AuthHint
{
    public string Key { get; init; } = "";
}

AuthHint hint = new() { Key = "sess-1" };
// CacheEntry entry = hint; // Compiler error — no relationship
CacheEntry entry = new() { Key = hint.Key }; // Must copy explicitly

abstract class AuthHandler
{
    public virtual string Provider => "base";
}

sealed class LtiHandler : AuthHandler
{
    public override string Provider => "lti";
}

AuthHandler h = new LtiHandler();
Console.WriteLine(h.Provider); // lti — CLR method table dispatch

// In JS, this is prototype lookup — you can mutate
// LtiHandler.prototype.Provider at runtime. C# slots are fixed in metadata.
